// Mappe le Statut actuel vers la relance à envoyer aujourd'hui
const STATUT_MAP = {
  'Message envoyé': { num: 1, relanceKey: 'Relance 1', nextStatut: 'Relance 1 envoyée', template: 'Relance 1' },
  'Relance 1 envoyée': { num: 2, relanceKey: 'Relance 2', nextStatut: 'Relance 2 envoyée', template: 'Relance 2' },
  'Relance 2 envoyée': { num: 3, relanceKey: 'Relance 3', nextStatut: 'Relance 3 envoyee', template: null }
};

function prop(props, name) {
  const p = props[name];
  if (!p) return '';
  if (p.type === 'title') return (p.title[0] && p.title[0].plain_text) || '';
  if (p.type === 'rich_text') return (p.rich_text[0] && p.rich_text[0].plain_text) || '';
  if (p.type === 'email') return p.email || '';
  if (p.type === 'select') return (p.select && p.select.name) || '';
  return '';
}

const todayISO = $today.toISODate();
const debut = $today.set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
const fenetreSecondes = 6 * 3600; // fenêtre 9h → 15h
const maintenant = $now;

const out = [];

for (const item of $input.all()) {
  const page = item.json;
  const props = page.properties || {};
  const statut = prop(props, 'Statut');
  const map = STATUT_MAP[statut];
  if (!map) continue; // rien à envoyer aujourd'hui pour cette fiche

  const email = prop(props, 'Mail pro');
  if (!email) continue; // pas d'email pro renseigné

  const nom = prop(props, 'Nom');
  const agence = prop(props, 'Agence');
  const prenom = (nom || '').trim().split(' ')[0] || '';
  const contenu = prop(props, map.relanceKey);

  const m = contenu.match(/^Objet\s*:\s*(.*?)\r?\n+([\s\S]*)$/i);
  const subject = m ? m[1].trim() : `Suivi — ${agence || nom}`;
  const body = m ? m[2].trim() : contenu.trim();

  const properties = {
    'Statut': { select: { name: map.nextStatut } },
    'Date dernière action': { date: { start: todayISO } }
  };
  if (map.template) {
    properties['Template utilisé'] = { select: { name: map.template } };
  }

  let sendAt = debut.plus({ seconds: Math.floor(Math.random() * fenetreSecondes) });
  if (sendAt < maintenant) sendAt = maintenant.plus({ seconds: 30 });

  out.push({
    json: {
      pageId: page.id,
      nom, prenom, agence, email,
      statutActuel: statut,
      relanceNum: map.num,
      subject, body,
      sendAt: sendAt.toISO(),
      patchBody: JSON.stringify({ properties })
    }
  });
}

out.sort((a, b) => (a.json.sendAt < b.json.sendAt ? -1 : 1));

return out;
